column78:
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE @table (@definition)';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -955 THEN
      RAISE;
    END IF;
END;

column79:
BEGIN
  EXECUTE IMMEDIATE 'TRUNCATE TABLE %temp_prefix%%session_id%@table';
  EXECUTE IMMEDIATE 'DROP TABLE %temp_prefix%%session_id%@table';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -942 THEN
      RAISE;
    END IF;
END;

