column276:
HINT SORT_ON_KEY(@type:@sortkey)
CREATE TABLE @d
@type SORTKEY(@sortkey)
AS
WITH @a AS @b SELECT
@c
FROM
@e;

column277:
HINT DISTRIBUTE_ON_KEY(@key) SORT_ON_KEY(@type:@sortkey)
CREATE TABLE @d
DISTKEY(@key)
@type SORTKEY(@sortkey)
AS
WITH @a AS @b SELECT
@c
FROM
@e;

column345:
HINT DISTRIBUTE_ON_KEY(@key) @hint
CREATE TABLE @d WITH (DISTRIBUTION = HASH(@key))
AS
WITH @a AS @b SELECT
@c
FROM
@e;

column346:
CREATE TABLE @d WITH (DISTRIBUTION = HASH(subject_id))
AS
WITH @a AS @b SELECT
@c1 subject_id, @c2
FROM
@e;

